// Handles: plain string, text blocks ({text}), tool_result blocks ({content: string}).
// Skips tool_use blocks ({input}) which carry no readable text.
function extractText(content) {
  if (typeof content === 'string') return content;
  if (!Array.isArray(content)) return '';
  return content
    .map(b => b['text'] || (typeof b['content'] === 'string' ? b['content'] : ''))
    .filter(Boolean)
    .join('\n');
}

// ─── Session / user ──────────────────────────────────────────────────────────
__e['session_id'] = meta['session_id'] || '';
__e['user_id']    = meta['login_name'] || '';

// ─── Timing ──────────────────────────────────────────────────────────────────
// DateTime64(3) expects milliseconds.
