const lastReqMsg  = reqBodyMsgs.length > 0 ? reqBodyMsgs[reqBodyMsgs.length - 1] : null;
const inputText   = lastReqMsg ? extractText(lastReqMsg['content']) : '';
__e['span_id']    = String(startMs);
__e['parent_span_id'] = '';
__e['span_name'] = 'llm.messages';
__e['span_kind'] = 'CLIENT';

